import{_ as i,o as a,c as t,al as s}from"./chunks/framework.7vp1BMOE.js";const u=JSON.parse('{"title":"Software Bill of Materials (SBOM)","description":"","frontmatter":{},"headers":[],"relativePath":"zh/contribute/sbom.md","filePath":"zh/contribute/sbom.md"}'),n={name:"zh/contribute/sbom.md"};function o(l,e,r,d,h,c){return a(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="software-bill-of-materials-sbom" tabindex="-1">Software Bill of Materials (SBOM) <a class="header-anchor" href="#software-bill-of-materials-sbom" aria-label="Permalink to &quot;Software Bill of Materials (SBOM)&quot;">​</a></h1><p>PX4 generates a <a href="https://www.ntia.gov/SBOM" target="_blank" rel="noreferrer">Software Bill of Materials</a> for every firmware build in <a href="https://spdx.github.io/spdx-spec/v2.3/" target="_blank" rel="noreferrer">SPDX 2.3</a> JSON format.</p><h2 id="why-sbom" tabindex="-1">Why SBOM? <a class="header-anchor" href="#why-sbom" aria-label="Permalink to &quot;Why SBOM?&quot;">​</a></h2><ul><li><strong>Regulatory compliance</strong>: The EU Cyber Resilience Act (CRA) requires SBOMs for products with digital elements (reporting obligations begin in September 2026).</li><li><strong>Supply chain transparency</strong>: SBOMs enumerate every component compiled into firmware, enabling users and integrators to audit dependencies.</li><li><strong>NTIA minimum elements</strong>: Each SBOM satisfies all seven <a href="https://www.ntia.gov/report/2021/minimum-elements-software-bill-materials-sbom" target="_blank" rel="noreferrer">NTIA required fields</a>: supplier, component name, version, unique identifier, dependency relationship, author, and timestamp.</li></ul><h2 id="format" tabindex="-1">Format <a class="header-anchor" href="#format" aria-label="Permalink to &quot;Format&quot;">​</a></h2><p>PX4 uses SPDX 2.3 JSON. SPDX is the Linux Foundation&#39;s own standard (ISO/IEC 5962), aligning with PX4&#39;s position as a Dronecode/LF project. Zephyr RTOS also uses SPDX.</p><p>Each SBOM contains:</p><ul><li><strong>Primary package</strong>: The PX4 firmware for a specific board target, marked with <code>primaryPackagePurpose: FIRMWARE</code>.</li><li><strong>Git submodules</strong>: All third-party libraries included via git submodules (~33 packages), with SPDX license identifiers and commit hashes.</li><li><strong>Python build dependencies</strong>: Packages from <code>Tools/setup/requirements.txt</code> marked as <code>BUILD_DEPENDENCY_OF</code> the firmware.</li><li><strong>Board-specific modules</strong>: Internal PX4 modules compiled for the target board.</li><li><strong>Compiler</strong>: The C compiler used for the build.</li></ul><p>Typical SBOM size: 70-100 packages, ~500 lines, ~20 KB JSON.</p><h2 id="generation" tabindex="-1">Generation <a class="header-anchor" href="#generation" aria-label="Permalink to &quot;Generation&quot;">​</a></h2><p>SBOMs are generated automatically as part of every CMake build. The output file is:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>build/&lt;target&gt;/&lt;target&gt;.sbom.spdx.json</span></span></code></pre></div><p>例如：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>build/px4_fmu-v6x_default/px4_fmu-v6x_default.sbom.spdx.json</span></span></code></pre></div><p>The generator script is <code>Tools/ci/generate_sbom.py</code>. It requires PyYAML (<code>pyyaml</code>) for loading license overrides.</p><h3 id="cmake-integration" tabindex="-1">CMake Integration <a class="header-anchor" href="#cmake-integration" aria-label="Permalink to &quot;CMake Integration&quot;">​</a></h3><p>The <code>sbom</code> CMake target is included in the default <code>ALL</code> target. The relevant CMake module is <code>cmake/sbom.cmake</code>.</p><h3 id="disabling-sbom-generation" tabindex="-1">Disabling SBOM Generation <a class="header-anchor" href="#disabling-sbom-generation" aria-label="Permalink to &quot;Disabling SBOM Generation&quot;">​</a></h3><p>Set the environment variable before building. This is checked at CMake configure time, so a clean build or reconfigure is required:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PX4_SBOM_DISABLE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> px4_fmu-v6x_default</span></span></code></pre></div><p>If the build directory already exists, force a reconfigure:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PX4_SBOM_DISABLE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -B</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build/px4_fmu-v6x_default</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span></code></pre></div><h3 id="manual-generation" tabindex="-1">Manual Generation <a class="header-anchor" href="#manual-generation" aria-label="Permalink to &quot;Manual Generation&quot;">​</a></h3><p>You can also run the generator directly:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Tools/ci/generate_sbom.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    --source-dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    --board</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> px4_fmu-v6x_default</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    --modules-file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build/px4_fmu-v6x_default/config_module_list.txt</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    --compiler</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> arm-none-eabi-gcc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build/px4_fmu-v6x_default/px4_fmu-v6x_default.sbom.spdx.json</span></span></code></pre></div><h2 id="artifacts" tabindex="-1">Artifacts <a class="header-anchor" href="#artifacts" aria-label="Permalink to &quot;Artifacts&quot;">​</a></h2><p>SBOMs are available in:</p><table tabindex="0"><thead><tr><th>Location</th><th>Path</th></tr></thead><tbody><tr><td>Build directory</td><td><code>build/&lt;target&gt;/&lt;target&gt;.sbom.spdx.json</code></td></tr><tr><td>GitHub Releases</td><td>Alongside <code>.px4</code> firmware files</td></tr><tr><td>S3</td><td>Same directory as firmware artifacts</td></tr></tbody></table><h2 id="validation" tabindex="-1">Validation <a class="header-anchor" href="#validation" aria-label="Permalink to &quot;Validation&quot;">​</a></h2><p>Validate an SBOM against the SPDX JSON schema:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">import json</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">doc = json.load(open(&#39;build/px4_sitl_default/px4_sitl_default.sbom.spdx.json&#39;))</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">assert doc[&#39;spdxVersion&#39;] == &#39;SPDX-2.3&#39;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">assert doc[&#39;dataLicense&#39;] == &#39;CC0-1.0&#39;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">assert len(doc[&#39;packages&#39;]) &gt; 0</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">print(f&#39;Valid: {len(doc[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">packages</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">])} packages&#39;)</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span></code></pre></div><p>For full schema validation, use the <a href="https://tools.spdx.org/app/validate/" target="_blank" rel="noreferrer">SPDX online validator</a> or the <code>spdx-tools</code> CLI.</p><h2 id="license-detection" tabindex="-1">License Detection <a class="header-anchor" href="#license-detection" aria-label="Permalink to &quot;License Detection&quot;">​</a></h2><p>Submodule licenses are identified through a combination of auto-detection and manual overrides.</p><h3 id="auto-detection" tabindex="-1">Auto-Detection <a class="header-anchor" href="#auto-detection" aria-label="Permalink to &quot;Auto-Detection&quot;">​</a></h3><p>The generator reads the first 100 lines of each submodule&#39;s LICENSE or COPYING file and matches keywords against known patterns. Copyleft licenses (GPL, LGPL, AGPL) are checked before permissive ones to prevent false positives.</p><p>Supported patterns include:</p><table tabindex="0"><thead><tr><th>SPDX Identifier</th><th>Matched Keywords</th></tr></thead><tbody><tr><td>GPL-3.0-only</td><td>&quot;GNU GENERAL PUBLIC LICENSE&quot;, &quot;Version 3&quot;</td></tr><tr><td>GPL-2.0-only</td><td>&quot;GNU GENERAL PUBLIC LICENSE&quot;, &quot;Version 2&quot;</td></tr><tr><td>LGPL-3.0-only</td><td>&quot;GNU LESSER GENERAL PUBLIC LICENSE&quot;, &quot;Version 3&quot;</td></tr><tr><td>LGPL-2.1-only</td><td>&quot;GNU Lesser General Public License&quot;, &quot;Version 2.1&quot;</td></tr><tr><td>AGPL-3.0-only</td><td>&quot;GNU AFFERO GENERAL PUBLIC LICENSE&quot;, &quot;Version 3&quot;</td></tr><tr><td>Apache-2.0</td><td>&quot;Apache License&quot;, &quot;Version 2.0&quot;</td></tr><tr><td>MIT</td><td>&quot;Permission is hereby granted&quot;</td></tr><tr><td>BSD-3-Clause</td><td>&quot;Redistribution and use&quot;, &quot;Neither the name&quot;</td></tr><tr><td>BSD-2-Clause</td><td>&quot;Redistribution and use&quot;, &quot;THIS SOFTWARE IS PROVIDED&quot;</td></tr><tr><td>ISC</td><td>&quot;Permission to use, copy, modify, and/or distribute&quot;</td></tr><tr><td>EPL-2.0</td><td>&quot;Eclipse Public License&quot;, &quot;2.0&quot;</td></tr><tr><td>Unlicense</td><td>&quot;The Unlicense&quot;, &quot;unlicense.org&quot;</td></tr></tbody></table><p>If no pattern matches, the license is set to <code>NOASSERTION</code>.</p><h3 id="override-file" tabindex="-1">Override File <a class="header-anchor" href="#override-file" aria-label="Permalink to &quot;Override File&quot;">​</a></h3><p>When auto-detection fails or returns the wrong result, add an entry to <code>Tools/ci/license-overrides.yaml</code>:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">overrides</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  src/lib/crypto/libtomcrypt</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    license</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Unlicense&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    comment</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Public domain dedication. Functionally equivalent to Unlicense.&quot;</span></span></code></pre></div><p>Each entry maps a submodule path to its correct SPDX license identifier. The optional <code>comment</code> field is emitted as <code>licenseComments</code> in the SBOM, providing context for auditors reviewing complex licensing situations (dual licenses, composite LICENSE files, public domain dedications).</p><h3 id="copyleft-guardrail" tabindex="-1">Copyleft Guardrail <a class="header-anchor" href="#copyleft-guardrail" aria-label="Permalink to &quot;Copyleft Guardrail&quot;">​</a></h3><p>The <code>--verify-licenses</code> command flags submodules with copyleft licenses (GPL, LGPL, AGPL) in a dedicated warning section. This is informational only and does not cause a failure. It helps maintainers track copyleft obligations when adding new submodules.</p><h3 id="platform-filtering" tabindex="-1">Platform Filtering <a class="header-anchor" href="#platform-filtering" aria-label="Permalink to &quot;Platform Filtering&quot;">​</a></h3><p>Submodules under <code>platforms/nuttx/</code> are excluded from POSIX and QURT SBOMs. The <code>--platform</code> argument (set automatically by CMake via <code>\${PX4_PLATFORM}</code>) controls which platform-specific submodules are included. This ensures SITL builds do not list NuttX RTOS packages.</p><h3 id="验证" tabindex="-1">验证 <a class="header-anchor" href="#验证" aria-label="Permalink to &quot;验证&quot;">​</a></h3><p>Run the verify command to check detection for all submodules:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Tools/ci/generate_sbom.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --verify-licenses</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --source-dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span></code></pre></div><p>This prints each submodule with its detected license, any override, and the final value. It exits non-zero if any checked-out submodule resolves to <code>NOASSERTION</code> without an override. Copyleft warnings are printed after the main table.</p><h3 id="adding-a-new-submodule" tabindex="-1">Adding a New Submodule <a class="header-anchor" href="#adding-a-new-submodule" aria-label="Permalink to &quot;Adding a New Submodule&quot;">​</a></h3><ol><li>Add the submodule normally.</li><li>Run <code>--verify-licenses</code> to confirm the license is detected.</li><li>If detection fails, add an override to <code>Tools/ci/license-overrides.yaml</code>.</li><li>If the license is not in the SPDX list, use <code>LicenseRef-&lt;name&gt;</code>.</li></ol><h3 id="eu-cra-compliance" tabindex="-1">EU CRA Compliance <a class="header-anchor" href="#eu-cra-compliance" aria-label="Permalink to &quot;EU CRA Compliance&quot;">​</a></h3><p>The EU Cyber Resilience Act requires SBOMs for products with digital elements. The goal is zero <code>NOASSERTION</code> licenses in shipped firmware SBOMs. Every submodule should have either a detected or overridden license. The <code>--verify-licenses</code> check enforces this in CI.</p><h2 id="what-s-in-an-sbom" tabindex="-1">What&#39;s in an SBOM <a class="header-anchor" href="#what-s-in-an-sbom" aria-label="Permalink to &quot;What&#39;s in an SBOM&quot;">​</a></h2><p>This section is for integrators, compliance teams, and anyone reviewing SBOM artifacts.</p><h3 id="where-to-find-sboms" tabindex="-1">Where to Find SBOMs <a class="header-anchor" href="#where-to-find-sboms" aria-label="Permalink to &quot;Where to Find SBOMs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Location</th><th>Path</th></tr></thead><tbody><tr><td>Build directory</td><td><code>build/&lt;target&gt;/&lt;target&gt;.sbom.spdx.json</code></td></tr><tr><td>GitHub Releases</td><td>Alongside <code>.px4</code> firmware files</td></tr><tr><td>S3</td><td>Same directory as firmware artifacts</td></tr></tbody></table><h3 id="reading-the-json" tabindex="-1">Reading the JSON <a class="header-anchor" href="#reading-the-json" aria-label="Permalink to &quot;Reading the JSON&quot;">​</a></h3><p>Each SBOM is a single JSON document following SPDX 2.3. Key fields:</p><ul><li><strong><code>packages</code></strong>: Array of all components. Each has <code>name</code>, <code>versionInfo</code>, <code>licenseConcluded</code>, and <code>SPDXID</code>.</li><li><strong><code>relationships</code></strong>: How packages relate. <code>CONTAINS</code> means a submodule is compiled into firmware. <code>BUILD_DEPENDENCY_OF</code> means a tool used only during build.</li><li><strong><code>licenseConcluded</code></strong>: The SPDX license identifier determined for that package.</li><li><strong><code>licenseComments</code></strong>: Free-text explanation for complex cases (dual licenses, composite files, public domain).</li><li><strong><code>externalRefs</code></strong>: Package URLs (purls) linking to GitHub repos or PyPI.</li></ul><h3 id="understanding-noassertion" tabindex="-1">Understanding NOASSERTION <a class="header-anchor" href="#understanding-noassertion" aria-label="Permalink to &quot;Understanding NOASSERTION&quot;">​</a></h3><p><code>NOASSERTION</code> means no license could be determined. For submodules, this happens when:</p><ul><li>The submodule is not checked out (common in CI shallow clones).</li><li>No LICENSE/COPYING file exists.</li><li>The LICENSE file does not match any known pattern and no override is configured.</li></ul><p>For shipped firmware, <code>NOASSERTION</code> should be resolved by adding an override. For build-only dependencies (Python packages), <code>NOASSERTION</code> is acceptable since these are not compiled into the firmware binary.</p>`,66)])])}const k=i(n,[["render",o]]);export{u as __pageData,k as default};
